contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address pool, address member, uint amount, address otherPool) public {
        require(pool != address(0) && member != address(0), "zero");

        uint beforePool = c.getmapAddress_LPBalance(pool);
        uint beforeOther = c.getmapAddress_LPBalance(otherPool);

        uint ret = c.mintSynth(member, amount);

        uint afterPool = c.getmapAddress_LPBalance(pool);
        uint afterOther = c.getmapAddress_LPBalance(otherPool);

        uint deltaPool = afterPool - beforePool;
        uint deltaOther = afterOther - beforeOther;

        if (otherPool == pool) {
            assert(deltaPool == deltaOther);
        } else {
            assert(deltaOther == 0);
        }

        assert(ret == amount);
    }
}

