contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, address spender, uint256 amount) public {
        require(owner != address(0) && spender != address(0), "bad actors");

        c = C(c);
        // The test's EOA is the only caller that can act as msg.sender for c if we call through c.
        // Directly calling c.approve(...) makes c's msg.sender this test contract, but owner is a param.
        // To make owner observable as a param we use transferFrom-style? No: we cannot impersonate owner.
        // Instead use the fact that approve sets allowance(msg.sender, spender).
        // So test with owner == address(this) only? But the rule should be general; use spender and amount.
        // Since only c's msg.sender can be this test contract, the owner effectively is address(this).
        // We still take owner as param to avoid hard-coding and require it equals address(this).
        require(owner == address(this), "owner must be test");

        c.approve(spender, amount);
        uint256 got = c.allowance(owner, spender);

        assert(got == amount);
    }

    receive() external payable {}
}

