contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 addedValue) public payable {
        uint256 beforeAllowance = c.allowance(address(this), spender);

        bool reverted;
        try c.increaseAllowance(spender, addedValue) returns (bool ok) {
            reverted = !ok;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(address(this), spender);

        if (spender == address(0)) {
            assert(reverted && afterAllowance == beforeAllowance);
        } else {
            assert(!reverted && afterAllowance == beforeAllowance + addedValue);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 addedValue) public payable {
        require(spender != address(0));

        uint256 beforeAllowance = c.allowance(address(this), spender);

        c.increaseAllowance(spender, addedValue);

