contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address sender, address recipient, uint256 amount) public {
        // Ensure we have a real spender and sender to work with.
        require(recipient != address(0), "recipient0");

        // Read the pre-existing allowance and balance through the public surface.
        uint256 allowanceBefore = c.allowance(sender, address(this));
        uint256 balanceBefore = c.balanceOf(sender);

        bool unlimited = (allowanceBefore == type(uint256).max);
        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 allowanceAfter = c.allowance(sender, address(this));
        uint256 balanceAfter = c.balanceOf(sender);
        uint256 totalSupplyAfter = c.totalSupply();

        if (unlimited) {
            // The contract skips allowance bookkeeping when the spender is unlimited,
            // so any failure must come from the sender's balance, and a success for
            // any amount must be impossible when the sender lacks funds.
            assert(reverted == (balanceBefore < amount));
            if (!reverted) {
                assert(allowanceAfter == allowanceBefore);
            }
        } else {
            // Reverts exactly when the spender is under-approved or the sender lacks funds.
            bool expectRevert = (allowanceBefore < amount) || (balanceBefore < amount);
            assert(reverted == expectRevert);
            if (!reverted) {
                assert(allowanceAfter == allowanceBefore - amount);
                assert(balanceAfter == balanceBefore - amount);
                assert(c.balanceOf(recipient) >= amount);
            } else {
                assert(allowanceAfter == allowanceBefore);
                assert(balanceAfter == balanceBefore);
            }
        }
        assert(totalSupplyAfter == c.totalSupply());
    }

    receive() external payable {}
}

