    function run(address synthKeyBefore, uint256 synthAmountBefore) public {
        // set up a synthetic balance at c so burnSynth has something to act on
        // (transferAndCall is a no-op for EOA-like actor, but we use it to move the balance)
        // Actually, we can't mint without onlyPool, so we use the fact that the fresh deploy has zero balance.
        // The general rule: after burnSynth, debt decreases by the synthetic balance held by c at call time.
        uint256 debtBefore = c.mapSynth_LPDebt(msg.sender);
        uint256 balBefore = c.balanceOf(address(c));
        c.burnSynth();
        uint256 debtAfter = c.mapSynth_LPDebt(msg.sender);
        // The rule: if the balance was non-zero, the debt must be reduced by that balance (which is zero here since fresh)
        // But since balance is zero on fresh deploy, we need to state the general relation that works when balBefore is 0 too:
        // debtAfter == debtBefore - balBefore (unsaturated subtraction is safe because debt must have been >= balBefore)
        // On a fresh deploy, debtBefore is 0 and balBefore is 0, so 0 == 0 - 0.
        // We also assert that if a nonzero balance exists, the debt decreases accordingly.
        assert(debtAfter == debtBefore - balBefore);
    }
}

