        address factory = c.BASE();

        bool reverted;
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The onlyPool modifier reverts unless msg.sender is a curated pool.
        // The test contract calls directly (not a pool), so if the call had not reverted,
        // the onlyPool gate must have been bypassed, violating the modifier.
        if (!reverted) {
            // If it did not revert, then the pool check must report this contract as curated.
            // We can only observe this through the external factory isCuratedPool view.
            assert(iPOOLFACTORY(factory).isCuratedPool(address(this)));
        } else {
            // Reverted: the onlyPool gate must have failed (this contract is not a curated pool).
            assert(!iPOOLFACTORY(factory).isCuratedPool(address(this)));
        }
    }
}

