contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address member, uint amount, uint lpTranche, uint debtSeed) public payable {
        require(member != address(0));
        require(amount > 0);

        // Setup: make c's stored LP balance for this test caller (msg.sender acting as pool)
        // large enough that _getAddedLPAmount > 0, without exceeding the LP token balance
        // actually held by c (extra LP is transferred in through the real c->transfer path).
        // We only use observable public functions: seed via mintSynth itself is not possible
        // before comparing, so we just record before-values and let mintSynth run.
        uint balBefore = c.balanceOf(member);
        uint debtBefore = c.getmapAddress_LPDebt(msg.sender);
        uint lpBalBefore = c.getmapAddress_LPBalance(msg.sender);

        (bool ok, bytes memory data) = address(c).call(
            abi.encodeWithSelector(c.mintSynth.selector, member, amount)
        );

        uint balAfter = c.balanceOf(member);
        uint debtAfter = c.getmapAddress_LPDebt(msg.sender);
        uint lpBalAfter = c.getmapAddress_LPBalance(msg.sender);

        // General rule: whoever the pool is, minting `amount` synthetic units credits exactly
        // `amount` to `member` (the pool's own LP-debt in the target synth is bumped by the same amount),
        // and the pool's tracked LP balance can never decrease from this operation.
        assert(
            !ok
                ? (balAfter == balBefore && debtAfter == debtBefore && lpBalAfter == lpBalBefore)
                : (balAfter == balBefore + amount && debtAfter == debtBefore + amount && lpBalAfter >= lpBalBefore)
        );
    }

    receive() external payable {}
}

