contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address member, uint amount, address pool) public {
        require(amount > 0, "amount>0");
        require(member != address(0), "member!=0");
        require(pool != address(0), "pool!=0");

        // read pre-state via public getter before the mintSynth call
        uint before = c.mapSynth_LPBalance(pool);

        // drive the public entry mintSynth through its public/external surface
        // Note: onlyPool modifier is checked against iPOOLFACTORY curated pools,
        // so a revert is expected unless pool is the actual curated pool.
        bool reverted;
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // read post-state via public getter
            uint afterBal = c.mapSynth_LPBalance(pool);
            // the stored LP balance at the caller key must be monotonic non-decreasing
            assert(afterBal >= before);
        } else {
            // if the call reverts, no state change should have occurred at that key
            uint afterBal = c.mapSynth_LPBalance(pool);
            assert(afterBal == before);
        }
    }
}

